return {
  CAREER = "H01-PX05(R)是隶属于逆巴比伦塔的上位净化者，代号“信使”。作为麦戈拉超云端安全防卫系统的关键成员之一，H01-PX05(R)结合了部分前代净化者的心智数据，拥有现役净化者中最强的单体超视距打击能力。除了高效的作战能力，信使在工作时也能较为有效地与各个扇区的智能体进行沟通，确保与扇区建立良好的合作关系。而一旦确认了交流对象的威胁性，信使也能迅速切换为战斗形态，第一时间消灭潜在或已有的风险。\n\n受到麦戈拉全面熵化的影响，信使代表净化者与绿洲达成了合作协议，二者在对熵阵营及反叛净化者阵营的作战中都表现出了极佳的协作性。而出于对绿洲和教授本人的兴趣，信使也表达出了建立深入合作的意愿。",
  INFOSTORY1 = "麦戈拉云端的净化者与整个逆巴比伦塔最初的结构设计，来自42lab的网络安全专家约米耶。在设计了担任统合和领袖任务的H01-PX01和H01-PX02，以及作为辅助和后备的H01-PX01(I)后，约米耶开始着重设计以病毒查杀功能为主的上位净化者。约米耶以防卫，检测，杀毒，修复以及自我检测等多个功能为核心设计出原型，并录入了万圣之殿中。万圣之殿则会根据云端当前情况，针对需求组合功能创造出对应的上位净化者。\n\n而信使便是结合了部分前代净化者的心智数据后，针对病毒检测和精确杀毒二项指标迭代演化后的个体。凭借优异的检索算法，信使可以精确锁定病毒，并且在病毒做出反应之前以超视距的方式将病毒查杀。",
  INFOSTORY2 = "考虑到即使是上位净化者也依旧有可能在保卫云端的过程中损耗，万圣之殿的程式之中预载了大量上位净化者的形象数据。在上位净化者出现空缺之时，万圣之殿便会依照数据与功能来生成新的净化者形象。对于一款杀毒软件而言，这项功能并没有任何实质性的作用。虽然约米耶坚称这是为了方便可视化管理，但是更多人猜测这只是约米耶单纯想要满足自己设计的执念罢了。\n\n然而信使的外形数据之中出现了多项被篡改的信息，这极大的影响了信使的形象生成。即使在净化者内部都有人提出，她的形象过于接近某一位前代净化者——伊拉。在云端与现实断联的当下，外界已经无法左右净化者的设置。唯一的可能便是净化者内部有人使用权限对信使的形象产生了影响。",
  INFOSTORY3 = "作为同一时期诞生的上位净化者，信使与圣餐之间有着近似姐妹的联系。虽然两人的性格截然不同，甚至连所属的派系都并不一致，但是却经常会出现在同一场合。圣餐总是会不厌其烦地骚扰信使，而信使总会在圣餐闯祸的时候出面制止。用人类的关系性来描述的话，二人或许就像是经常斗嘴但是却形影不离的姐妹一般。\n\n然而根据信使自己的陈述，她与圣餐或许从来就没有成为过姐妹，也从未能够相互理解过。信使无法理解圣餐违背甚至亵渎净化者准则的行为。在多次产生冲突之后，信使选择了疏远圣餐。而在许久之后圣餐背叛之时，信使也未能成功挽回自己的“姐妹”。\n\n“或许分歧从最初就已经产生，当我发觉之时，一切为时已晚。”",
  INFOSTORY4 = "信使与绿洲的第一次接触并不算愉快。在信使的筛查系统中，离开云图扇区的流亡者们并不符合系统校验文档中的数据。信使履行了自己的职责，与绿洲一行人在恩格玛作战，试图将不符合系统校验的错误清除。然而其结果却是信使战败，被迫离开了自己的辖区。\n\n尽管作为上位净化者没有成功履行自己的使命，但管辖的扇区最终被自己眼中的邪灵所拯救，这使得信使对绿洲产生了莫大的兴趣。绿洲拥有足以击败上位净化者的潜力，又能够解决连净化者都难以处理的危机，甚至能使麦戈拉数个扇区自主选择脱离净化者的保护，展开沙盒屏障，这每一项报告都足以让上位净化者忌惮。为了确保绿洲的立场，对绿洲进行监视，信使曾希望与绿洲进行交涉。然而还未等信使行动，逆巴比伦塔就被晨星所控制且熵化，最终导致信使未能前往绿洲。",
  INFOSTORY5 = "在讨伐晨星的战斗之中，信使与绿洲正式展开了合作。虽然时间短暂，但是她也赢得了教授以及绿洲成员的信任。作为新一代云端的守卫者，信使来到了绿洲尝试建立更加亲密的关系。然而和平时严肃律己的姿态不同，信使很快就沉迷于对绿洲的探索之中，尤其是在晨曦介绍之下品尝绿洲的各种甜食。或许是为了挽回净化者的形象，信使不断强调自己是为了观察和监视绿洲。\n\n在信使的努力之下，原本关系就已经缓和了许多的绿洲与净化者，终于能够打破隔阂，迈向新的未来。绿洲与净化者的合作也愈发紧密，共同建立了新的云端安全体系。当然对于部分行为，诸如在全麦戈拉放置直播无人机、诡异的药物实验之类的行为，依旧是被净化者明令禁止。\n\n“话说回来，信使好像一直强调自己在监视教授。该不会……帕斯卡？喂！帕斯卡你去哪里！”\n——绿洲人事部录音。"
}
